B.ju=new A.bG(B.JV,['print("Hello, World!")\n',"def fibonacci(n):\n    a, b = 0, 1\n    for _ in range(n):\n        print(a, end=' ')\n        a, b = b, a + b\n    print()\n\nfibonacci(10)\n",'import math\n\n# Basic arithmetic\nresult = 10 + 5 * 2\nprint(f"10 + 5 * 2 = {result}")\n\n# Math functions\nprint(f"Square root of 16: {math.sqrt(16)}")\nprint(f"Pi: {math.pi}")\n','# List creation and manipulation\nnumbers = [1, 2, 3, 4, 5]\nprint(f"Original list: {numbers}")\n\n# List comprehension\nsquares = [x**2 for x in numbers]\nprint(f"Squares: {squares}")\n\n# Filter even numbers\nevens = [x for x in numbers if x % 2 == 0]\nprint(f"Even numbers: {evens}")\n'],t.li)
